CREATE TABLE room_safety_report (report_id VARCHAR(36) PRIMARY KEY,room_id BIGINT NULL,reporter_id BIGINT NOT NULL,target_player_id BIGINT NULL,category VARCHAR(24) NOT NULL,detail VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,created_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uq_room_report_idem(reporter_id,idempotency_key),KEY ix_room_report_status(status,created_at));
CREATE TABLE room_safety_mute (room_id BIGINT NOT NULL,player_id BIGINT NOT NULL,muted_by BIGINT NOT NULL,reason VARCHAR(256) NOT NULL,muted_until TIMESTAMP(3) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,created_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(room_id,player_id),UNIQUE KEY uq_room_mute_idem(muted_by,idempotency_key));
CREATE TABLE room_safety_location (room_id BIGINT NOT NULL,player_id BIGINT NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,accuracy_meters DECIMAL(9,2) NOT NULL,observed_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(room_id,player_id));
